export const calculateAirQualityLevel = (pm25: number): AirQualityLevel => {
  if (pm25 <= 15.0) return 'good';
  if (pm25 <= 35.4) return 'moderate';
  if (pm25 <= 55.4) return 'unhealthy';
  return 'hazardous';
};

